// Generated by scripts/build-pages-data.mjs. Do not edit.
const YIJING_TEXT=[{"name":"乾","originalName":"乾","judgment":"乾：元，亨，利，貞。","lines":["初九：潛龍，勿用。","九二：見龍在田，利見大人。","九三：君子終日乾乾，夕惕，若厲，無咎。","九四：或躍在淵，無咎。","九五：飛龍在天，利見大人。","上九：亢龍有悔。"],"special":"用九：見群龍無首，吉。"},{"name":"坤","originalName":"坤","judgment":"坤：元，亨，利牝馬之貞。君子有攸往，先迷後得主，利西南得朋，東北喪朋。安貞，吉。","lines":["初六：履霜，堅冰至。","六二：直，方，大，不習無不利。","六三：含章可貞。或從王事，無成有終。","六四：括囊；無咎，無譽。","六五：黃裳，元吉。","上六：戰龍於野，其血玄黃。"],"special":"用六：利永貞。"},{"name":"屯","originalName":"屯","judgment":"屯：元，亨，利，貞，勿用，有攸往，利建侯。","lines":["初九：磐桓；利居貞，利建侯。","六二：屯如邅如，乘馬班如。匪寇婚媾，女子貞不字，十年乃字。","六三：既鹿無虞，惟入于林中，君子幾不如舍，往吝。","六四：乘馬班如，求婚媾，往吉，無不利。","九五：屯其膏，小貞吉，大貞凶。","上六：乘馬班如，泣血漣如。"],"special":""},{"name":"蒙","originalName":"蒙","judgment":"蒙：亨。匪我求童蒙，童蒙求我。初噬告，再三瀆，瀆則不告。利貞。","lines":["初六：發蒙，利用刑人，用說桎梏，以往吝。","九二：包蒙，吉；納婦，吉；子克家。","六三：勿用娶女；見金夫，不有躬，無攸利。","六四：困蒙，吝。","六五：童蒙，吉。","上九：擊蒙；不利為寇，利御寇。"],"special":""},{"name":"需","originalName":"需","judgment":"需：有孚，光亨，貞吉。利涉大川。","lines":["初九：需于郊。利用恆，無咎。","九二：需于沙。小有言，終吉。","九三：需于泥，致寇至。","六四：需于血，出自穴。","九五：需于酒食，貞吉。","上六：入于穴，有不速之客三人來，敬之終吉。"],"special":""},{"name":"讼","originalName":"訟","judgment":"訟：有孚，窒。惕中吉。終凶。利見大人，不利涉大川。","lines":["初六：不永所事，小有言，終吉。","九二：不克訟，歸而逋，其邑人三百戶，無眚。","六三：食舊德，貞厲，終吉，或從王事，無成。","九四：不克訟，復即命，渝安貞，吉。","九五：訟元吉。","上九：或錫之鞶帶，終朝三褫之。"],"special":""},{"name":"师","originalName":"師","judgment":"師：貞，丈人，吉無咎。","lines":["初六：師出以律，否臧凶。","九二：在師中，吉無咎，王三錫命。","六三：師或輿尸，凶。","六四：師左次，無咎。","六五：田有禽，利執言，無咎。長子帥師，弟子輿尸，貞凶。","上六：大君有命，開國承家，小人勿用。"],"special":""},{"name":"比","originalName":"比","judgment":"比：吉。原筮元永貞，無咎。不寧方來，後夫凶。","lines":["初六：有孚比之，無咎。有孚盈缶，終來有他，吉。","六二：比之自內，貞吉。","六三：比之匪人。","六四：外比之，貞吉。","九五：顯比，王用三驅，失前禽。邑人不誡，吉。","上六：比之無首，凶。"],"special":""},{"name":"小畜","originalName":"小畜","judgment":"小畜：亨。密雲不雨，自我西郊。","lines":["初九：復自道，何其咎，吉。","九二：牽復，吉。","九三：輿說輻，夫妻反目。","六四：有孚，血去。惕出，無咎。","九五：有孚攣如，富以其鄰。","上九：既雨既處，尚德載婦，貞厲。月幾望，君子征凶。"],"special":""},{"name":"履","originalName":"履","judgment":"履：履虎尾，不咥人，亨。","lines":["初九：素履，往無咎。","九二：履道坦坦，幽人貞吉。","六三：眇能視，跛能履，履虎尾，咥人，凶。武人為于大君。","九四：履虎尾，愬愬，終吉。","九五：夬履，貞厲。","上九：視履考祥，其旋元吉。"],"special":""},{"name":"泰","originalName":"泰","judgment":"泰：小往大來，吉亨。","lines":["初九：拔茅茹，以其彙，征吉。","九二：包荒，用馮河，不遐遺，朋亡，得尚于中行。","九三：無平不陂，無往不復，艱貞無咎。勿恤其孚，于食有福。","六四：翩翩不富，以其鄰，不戒以孚。","六五：帝乙歸妹，以祉元吉。","上六：城復于隍，勿用師。自邑告命，貞吝。"],"special":""},{"name":"否","originalName":"否","judgment":"否：否之匪人，不利君子貞，大往小來。","lines":["初六：拔茅茹，以其彙，貞吉亨。","六二：包承。小人吉，大人否亨。","六三：包羞。","九四：有命無咎，疇離祉。","九五：休否，大人吉。其亡其亡，繫于苞桑。","上九：傾否，先否後喜。"],"special":""},{"name":"同人","originalName":"同人","judgment":"同人：同人于野，亨。利涉大川，利君子貞。","lines":["初九：同人于門，無咎。","六二：同人于宗，吝。","九三：伏戎于莽，升其高陵，三歲不興。","九四：乘其墉，弗克攻，吉。","九五：同人，先號咷而後笑。大師克相遇。","上九：同人于郊，無悔。"],"special":""},{"name":"大有","originalName":"大有","judgment":"大有：元亨。","lines":["初九：無交害，匪咎，艱則無咎。","九二：大車以載，有攸往，無咎。","九三：公用亨于天子，小人弗克。","九四：匪其彭，無咎。","六五：厥孚交如，威如；吉。","上九：自天佑之，吉無不利。"],"special":""},{"name":"谦","originalName":"謙","judgment":"謙：亨，君子有終。","lines":["初六：謙謙君子，用涉大川，吉。","六二：鳴謙，貞吉。","九三：勞謙君子，有終吉。","六四：無不利，撝謙。","六五：不富，以其鄰，利用侵伐，無不利。","上六：鳴謙，利用行師，征邑國。"],"special":""},{"name":"豫","originalName":"豫","judgment":"豫：利建侯行師。","lines":["初六：鳴豫，凶。","六二：介于石，不終日，貞吉。","六三：盱豫，悔。遲有悔。","九四：由豫，大有得。勿疑。朋盍簪。","六五：貞疾，恆不死。","上六：冥豫，成有渝，無咎。"],"special":""},{"name":"随","originalName":"隨","judgment":"隨：元亨利貞，無咎。","lines":["初九：官有渝，貞吉。出門交有功。","六二：係小子，失丈夫。","六三：係丈夫，失小子。隨有求得，利居貞。","九四：隨有獲，貞凶。有孚在道，以明，何咎。","九五：孚于嘉，吉。","上六：拘系之，乃從維之。王用亨于西山。"],"special":""},{"name":"蛊","originalName":"蠱","judgment":"蠱：元亨，利涉大川。先甲三日，後甲三日。","lines":["初六：幹父之蠱，有子，考無咎，厲終吉。","九二：幹母之蠱，不可貞。","九三：幹父小有晦，無大咎。","六四：裕父之蠱，往見吝。","六五：幹父之蠱，用譽。","上九：不事王侯，高尚其事。"],"special":""},{"name":"临","originalName":"臨","judgment":"臨：元，亨，利，貞。至于八月有凶。","lines":["初九：咸臨，貞吉。","九二：咸臨，吉無不利。","六三：甘臨，無攸利。既憂之，無咎。","六四：至臨，無咎。","六五：知臨，大君之宜，吉。","上六：敦臨，吉無咎。"],"special":""},{"name":"观","originalName":"觀","judgment":"觀：盥而不薦，有孚顒若。","lines":["初六：童觀，小人無咎，君子吝。","六二：窺觀，利女貞。","六三：觀我生，進退。","六四：觀國之光，利用賓于王。","九五：觀我生，君子無咎。","上九：觀其生，君子無咎。"],"special":""},{"name":"噬嗑","originalName":"噬嗑","judgment":"噬嗑：亨。利用獄。","lines":["初九：履校滅趾，無咎。","六二：噬膚滅鼻，無咎。","六三：噬臘肉，遇毒；小吝，無咎。","九四：噬乾胏，得金矢，利艱貞，吉。","六五：噬乾肉，得黃金，貞厲，無咎。","上九：何校滅耳，凶。"],"special":""},{"name":"贲","originalName":"賁","judgment":"賁：亨。小利有所往。","lines":["初九：賁其趾，舍車而徒。","六二：賁其須。","九三：賁如濡如，永貞吉。","六四：賁如皤如，白馬翰如，匪寇婚媾。","六五：賁于丘園，束帛戔戔，吝，終吉。","上九：白賁，無咎。"],"special":""},{"name":"剥","originalName":"剝","judgment":"剝：不利有攸往。","lines":["初六：剝床以足，蔑貞凶。","六二：剝床以辨，蔑貞凶。","六三：剝之，無咎。","六四：剝床以膚，凶。","六五：貫魚，以宮人寵，無不利。","上九：碩果不食，君子得輿，小人剝廬。"],"special":""},{"name":"复","originalName":"復","judgment":"復：亨。出入無疾，朋來無咎。反復其道，七日來復，利有攸往。","lines":["初九：不復遠，無祗悔，元吉。","六二：休復，吉。","六三：頻復厲，無咎。","六四：中行獨復。","六五：敦復，無悔。","上六：迷復，凶，有災眚。用行師，終有大敗，以其國君，凶；至于十年，不克征。"],"special":""},{"name":"无妄","originalName":"無妄","judgment":"無妄：元，亨，利，貞。其匪正有眚，不利有攸往。","lines":["初九：無妄，往吉。","六二：不耕獲，不菑畬，則利有攸往。","六三：無妄之災，或繫之牛，行人之得，邑人之災。","九四：可貞，無咎。","九五：無妄之疾，勿藥有喜。","上九：無妄，行有眚，無攸利。"],"special":""},{"name":"大畜","originalName":"大畜","judgment":"大畜：利貞，不家食吉，利涉大川。","lines":["初九：有厲利已。","九二：輿說輻。","九三：良馬逐，利艱貞。日閑輿衛，利有攸往。","六四：童牛之牿，元吉。","六五：豶豕之牙，吉。","上九：何天之衢，亨。"],"special":""},{"name":"颐","originalName":"頤","judgment":"頤：貞吉。觀頤，自求口實。","lines":["初九：舍爾靈龜，觀我朵頤，凶。","六二：顛頤，拂經于丘頤，征凶。","六三：拂頤，貞凶，十年勿用，無攸利。","六四：顛頤吉，虎視眈眈，其欲逐逐，無咎。","六五：拂經，居貞吉，不可涉大川。","上九：由頤，厲吉，利涉大川。"],"special":""},{"name":"大过","originalName":"大過","judgment":"大過：棟橈，利有攸往，亨。","lines":["初六：藉用白茅，無咎。","九二：枯楊生稊，老夫得其女妻，無不利。","九三：棟橈，凶。","九四：棟隆，吉；有它吝。","九五：枯楊生華，老婦得士夫，無咎無譽。","上六：過涉滅頂，凶，無咎。"],"special":""},{"name":"坎","originalName":"坎","judgment":"坎：習坎，有孚，維心亨，行有尚。","lines":["初六：習坎，入于坎窞，凶。","九二：坎有險，求小得。","六三：來之坎坎，險且枕，入于坎窞，勿用。","六四：樽酒簋貳，用缶，納約自牖，終無咎。","九五：坎不盈，祗既平，無咎。","上六：係用徽纆，寘于叢棘，三歲不得，凶。"],"special":""},{"name":"离","originalName":"離","judgment":"離：利貞，亨。畜牝牛，吉。","lines":["初九：履錯然，敬之無咎。","六二：黃離，元吉。","九三：日昃之離，不鼓缶而歌，則大耋之嗟，凶。","九四：突如其來如，焚如，死如，棄如。","六五：出涕沱若，戚嗟若，吉。","上九：王用出征，有嘉折首，獲匪其醜，無咎。"],"special":""},{"name":"咸","originalName":"咸","judgment":"咸：亨，利貞，取女吉。","lines":["初六：咸其拇。","六二：咸其腓，凶，居吉。","九三：咸其股，執其隨，往吝。","九四：貞吉悔亡，憧憧往來，朋從爾思。","九五：咸其脢，無悔。","上六：咸其輔，頰，舌。"],"special":""},{"name":"恒","originalName":"恆","judgment":"恆：亨，無咎，利貞，利有攸往。","lines":["初六：浚恆，貞凶，無攸利。","九二：悔亡。","九三：不恆其德，或承之羞，貞吝。","九四：田無禽。","六五：恆其德，貞，婦人吉，夫子凶。","上六：振恆，凶。"],"special":""},{"name":"遁","originalName":"遯","judgment":"遯：亨，小利貞。","lines":["初六：遯尾，厲，勿用有攸往。","六二：執之用黃牛之革，莫之勝說。","九三：係遯，有疾厲，畜臣妾吉。","九四：好遯君子吉，小人否。","九五：嘉遯，貞吉。","上九：肥遯，無不利。"],"special":""},{"name":"大壮","originalName":"大壯","judgment":"大壯：利貞。","lines":["初九：壯于趾，征凶，有孚。","九二：貞吉。","九三：小人用壯，君子用罔，貞厲。羝羊觸藩，羸其角。","九四：貞吉悔亡，藩決不羸，壯于大輿之輹。","六五：喪羊于易，無悔。","上六：羝羊觸藩，不能退，不能遂，無攸利，艱則吉。"],"special":""},{"name":"晋","originalName":"晉","judgment":"晉：康侯用錫馬蕃庶，晝日三接。","lines":["初六：晉如，摧如，貞吉。罔孚，裕無咎。","六二：晉如，愁如，貞吉。受茲介福，于其王母。","六三：眾允，悔亡。","九四：晉如鼫鼠，貞厲。","六五：悔亡，失得勿恤，往吉無不利。","上九：晉其角，維用伐邑，厲吉無咎，貞吝。"],"special":""},{"name":"明夷","originalName":"明夷","judgment":"明夷：利艱貞。","lines":["初九：明夷于飛，垂其翼。君子于行，三日不食，有攸往，主人有言。","六二：明夷，夷于左股，用拯馬壯，吉。","九三：明夷于南狩，得其大首，不可疾貞。","六四：入于左腹，獲明夷之心，于出門庭。","六五：箕子之明夷，利貞。","上六：不明晦，初登于天，後入于地。"],"special":""},{"name":"家人","originalName":"家人","judgment":"家人：利女貞。","lines":["初九：閑有家，悔亡。","六二：無攸遂，在中饋，貞吉。","九三：家人嗃嗃，悔厲吉；婦子嘻嘻，終吝。","六四：富家，大吉。","九五：王假有家，勿恤吉。","上九：有孚威如，終吉。"],"special":""},{"name":"睽","originalName":"睽","judgment":"睽：小事吉。","lines":["初九：悔亡，喪馬勿逐，自復；見惡人無咎。","九二：遇主于巷，無咎。","六三：見輿曳，其牛掣，其人天且劓，無初有終。","九四：睽孤，遇元夫，交孚，厲無咎。","六五：悔亡，厥宗噬膚，往何咎。","上九：睽孤，見豕負塗，載鬼一車，先張之弧，後說之弧，匪寇婚媾，往遇雨則吉。"],"special":""},{"name":"蹇","originalName":"蹇","judgment":"蹇：利西南，不利東北；利見大人，貞吉。","lines":["初六：往蹇，來譽。","六二：王臣蹇蹇，匪躬之故。","九三：往蹇來反。","六四：往蹇來連。","九五：大蹇朋來。","上六：往蹇來碩，吉；利見大人。"],"special":""},{"name":"解","originalName":"解","judgment":"解：利西南，無所往，其來復吉。有攸往，夙吉。","lines":["初六：無咎。","九二：田獲三狐，得黃矢，貞吉。","六三：負且乘，致寇至，貞吝。","九四：解而拇，朋至斯孚。","六五：君子維有解，吉；有孚于小人。","上六：公用射隼，于高墉之上，獲之，無不利。"],"special":""},{"name":"损","originalName":"損","judgment":"損：有孚，元吉，無咎，可貞，利有攸往？曷之用，二簋可用享。","lines":["初九：已事遄往，無咎，酌損之。","九二：利貞，征凶，弗損益之。","六三：三人行，則損一人；一人行，則得其友。","六四：損其疾，使遄有喜，無咎。","六五：或益之，十朋之龜弗克違，元吉。","上九：弗損益之，無咎，貞吉，利有攸往，得臣無家。"],"special":""},{"name":"益","originalName":"益","judgment":"益：利有攸往，利涉大川。","lines":["初九：利用為大作，元吉，無咎。","六二：或益之，十朋之龜弗克違，永貞吉。王用享于帝，吉。","六三：益之用凶事，無咎。有孚中行，告公用圭。","六四：中行，告公從。利用為依遷國。","九五：有孚惠心，勿問元吉。有孚惠我德。","上九：莫益之，或擊之，立心勿恆，凶。"],"special":""},{"name":"夬","originalName":"夬","judgment":"夬：揚于王庭，孚號，有厲，告自邑，不利即戎，利有攸往。","lines":["初九：壯于前趾，往不勝為吝。","九二：惕號，莫夜有戎，勿恤。","九三：壯于頄，有凶。君子夬夬，獨行遇雨，若濡有慍，無咎。","九四：臀無膚，其行次且。牽羊悔亡，聞言不信。","九五：莧陸夬夬，中行無咎。","上六：無號，終有凶。"],"special":""},{"name":"姤","originalName":"姤","judgment":"姤：女壯，勿用取女。","lines":["初六：繫于金柅，貞吉，有攸往，見凶，羸豕孚蹢躅。","九二：包有魚，無咎，不利賓。","九三：臀無膚，其行次且，厲，無大咎。","九四：包無魚，起凶。","九五：以杞包瓜，含章，有隕自天。","上九：姤其角，吝，無咎。"],"special":""},{"name":"萃","originalName":"萃","judgment":"萃：亨。王假有廟，利見大人，亨，利貞。用大牲吉，利有攸往。","lines":["初六：有孚不終，乃亂乃萃，若號一握為笑，勿恤，往無咎。","六二：引吉，無咎，孚乃利用禴。","六三：萃如，嗟如，無攸利，往無咎，小吝。","九四：大吉，無咎。","九五：萃有位，無咎。匪孚，元永貞，悔亡。","上六：齎咨涕洟，無咎。"],"special":""},{"name":"升","originalName":"升","judgment":"升：元亨，用見大人，勿恤，南征吉。","lines":["初六：允升，大吉。","九二：孚乃利用禴，無咎。","九三：升虛邑。","六四：王用亨于岐山，吉無咎。","六五：貞吉，升階。","上六：冥升，利于不息之貞。"],"special":""},{"name":"困","originalName":"困","judgment":"困：亨，貞，大人吉，無咎，有言不信。","lines":["初六：臀困于株木，入于幽谷，三歲不覿。","九二：困于酒食，朱紱方來，利用亨祀，征凶，無咎。","六三：困于石，據于蒺藜，入于其宮，不見其妻，凶。","九四：來徐徐，困于金車，吝，有終。","九五：劓刖，困于赤紱，乃徐有說，利用祭祀。","上六：困于葛藟，于臲卼，曰動悔。有悔，征吉。"],"special":""},{"name":"井","originalName":"井","judgment":"井：改邑不改井，無喪無得，往來井井。汔至，亦未繘井，羸其瓶，凶。","lines":["初六：井泥不食，舊井無禽。","九二：井谷射鮒，甕敝漏。","九三：井渫不食，為我民惻，可用汲，王明，並受其福。","六四：井甃，無咎。","九五：井冽，寒泉食。","上六：井收勿幕，有孚無吉。"],"special":""},{"name":"革","originalName":"革","judgment":"革：己日乃孚，元亨利貞，悔亡。","lines":["初九：鞏用黃牛之革。","六二：己日乃革之，征吉，無咎。","九三：征凶，貞厲，革言三就，有孚。","九四：悔亡，有孚改命，吉。","九五：大人虎變，未占有孚。","上六：君子豹變，小人革面，征凶，居貞吉。"],"special":""},{"name":"鼎","originalName":"鼎","judgment":"鼎：元吉，亨。","lines":["初六：鼎顛趾，利出否，得妾以其子，無咎。","九二：鼎有實，我仇有疾，不我能即，吉。","九三：鼎耳革，其行塞，雉膏不食，方雨虧悔，終吉。","九四：鼎折足，覆公餗，其形渥，凶。","六五：鼎黃耳金鉉，利貞。","上九：鼎玉鉉，大吉，無不利。"],"special":""},{"name":"震","originalName":"震","judgment":"震：亨。震來虩虩，笑言啞啞。震驚百里，不喪匕鬯。","lines":["初九：震來虩虩，後笑言啞啞，吉。","六二：震來厲，億喪貝，躋于九陵，勿逐，七日得。","六三：震蘇蘇，震行無眚。","九四：震遂泥。","六五：震往來厲，億無喪，有事。","上六：震索索，視矍矍，征凶。震不于其躬，于其鄰，無咎。婚媾有言。"],"special":""},{"name":"艮","originalName":"艮","judgment":"艮：艮其背，不獲其身，行其庭，不見其人，無咎。","lines":["初六：艮其趾，無咎，利永貞。","六二：艮其腓，不拯其隨，其心不快。","九三：艮其限，列其夤，厲薰心。","六四：艮其身，無咎。","六五：艮其輔，言有序，悔亡。","上九：敦艮，吉。"],"special":""},{"name":"渐","originalName":"漸","judgment":"漸：女歸吉，利貞。","lines":["初六：鴻漸于干，小子厲，有言，無咎。","六二：鴻漸于磐，飲食衎衎，吉。","九三：鴻漸于陸，夫征不復，婦孕不育，凶；利御寇。","六四：鴻漸于木，或得其桷，無咎。","九五：鴻漸于陵，婦三歲不孕，終莫之勝，吉。","上九：鴻漸于逵，其羽可用為儀，吉。"],"special":""},{"name":"归妹","originalName":"歸妹","judgment":"歸妹：征凶，無攸利。","lines":["初九：歸妹以娣，跛能履，征吉。","九二：眇能視，利幽人之貞。","六三：歸妹以須，反歸以娣。","九四：歸妹愆期，遲歸有時。","六五：帝乙歸妹，其君之袂，不如其娣之袂良，月幾望，吉。","上六：女承筐無實，士刲羊無血，無攸利。"],"special":""},{"name":"丰","originalName":"豐","judgment":"豐：亨，王假之，勿憂，宜日中。","lines":["初九：遇其配主，雖旬無咎，往有尚。","六二：豐其蔀，日中見斗，往得疑疾，有孚發若，吉。","九三：豐其沛，日中見沫，折其右肱，無咎。","九四：豐其蔀，日中見斗，遇其夷主，吉。","六五：來章，有慶譽，吉。","上六：豐其屋，蔀其家，窺其戶，闃其無人，三歲不覿，凶。"],"special":""},{"name":"旅","originalName":"旅","judgment":"旅：小亨，旅貞吉。","lines":["初六：旅瑣瑣，斯其所取災。","六二：旅即次，懷其資，得童僕貞。","九三：旅焚其次，喪其童僕，貞厲。","九四：旅于處，得其資斧，我心不快。","六五：射雉一矢亡，終以譽命。","上九：鳥焚其巢，旅人先笑後號咷。喪牛于易，凶。"],"special":""},{"name":"巽","originalName":"巽","judgment":"巽：小亨，利攸往，利見大人。","lines":["初六：進退，利武人之貞。","九二：巽在床下，用史巫紛若，吉無咎。","九三：頻巽，吝。","六四：悔亡，田獲三品。","九五：貞吉悔亡，無不利。無初有終，先庚三日，後庚三日，吉。","上九：巽在床下，喪其資斧，貞凶。"],"special":""},{"name":"兑","originalName":"兌","judgment":"兌：亨，利貞。","lines":["初九：和兌，吉。","九二：孚兌，吉，悔亡。","六三：來兌，凶。","九四：商兌，未寧，介疾有喜。","九五：孚于剝，有厲。","上六：引兌。"],"special":""},{"name":"涣","originalName":"渙","judgment":"渙：亨。王假有廟，利涉大川，利貞。","lines":["初六：用拯馬壯，吉。","九二：渙奔其機，悔亡。","六三：渙其躬，無悔。","六四：渙其群，元吉。渙有丘，匪夷所思。","九五：渙汗其大號，渙王居，無咎。","上九：渙其血，去逖出，無咎。"],"special":""},{"name":"节","originalName":"節","judgment":"節：亨。苦節不可貞。","lines":["初九：不出戶庭，無咎。","九二：不出門庭，凶。","六三：不節若，則嗟若，無咎。","六四：安節，亨。","九五：甘節，吉；往有尚。","上六：苦節，貞凶，悔亡。"],"special":""},{"name":"中孚","originalName":"中孚","judgment":"中孚：豚魚，吉，利涉大川，利貞。","lines":["初九：虞吉，有他不燕。","九二：鳴鶴在陰，其子和之，我有好爵，吾與爾靡之。","六三：得敵，或鼓或罷，或泣或歌。","六四：月幾望，馬匹亡，無咎。","九五：有孚攣如，無咎。","上九：翰音登于天，貞凶。"],"special":""},{"name":"小过","originalName":"小過","judgment":"小過：亨，利貞，可小事，不可大事。飛鳥遺之音，不宜上宜下，大吉。","lines":["初六：飛鳥以凶。","六二：過其祖，遇其妣；不及其君，遇其臣；無咎。","九三：弗過防之，從或戕之，凶。","九四：無咎，弗過遇之。往厲必戒，勿用永貞。","六五：密雲不雨，自我西郊，公弋取彼在穴。","上六：弗遇過之，飛鳥離之，凶，是謂災眚。"],"special":""},{"name":"既济","originalName":"既濟","judgment":"既濟：亨，小利貞，初吉終亂。","lines":["初九：曳其輪，濡其尾，無咎。","六二：婦喪其茀，勿逐，七日得。","九三：高宗伐鬼方，三年克之，小人勿用。","六四：繻有衣袽，終日戒。","九五：東鄰殺牛，不如西鄰之禴祭，實受其福。","上六：濡其首，厲。"],"special":""},{"name":"未济","originalName":"未濟","judgment":"未濟：亨，小狐汔濟，濡其尾，無攸利。","lines":["初六：濡其尾，吝。","九二：曳其輪，貞吉。","六三：未濟，征凶，利涉大川。","九四：貞吉，悔亡，震用伐鬼方，三年有賞于大國。","六五：貞吉，無悔，君子之光，有孚，吉。","上九：有孚于飲酒，無咎，濡其首，有孚失是。"],"special":""}];
export const waite=[["愚行 · 狂热 · 放纵","疏忽 · 漠然 · 虚荣","韦特将愚者与愚行、狂热和放纵相连；这与现代常见的“崭新开始”解读不同。","逆位指疏忽、心不在焉、漫不经心，也可指冷漠或虚荣。"],["技巧 · 意志 · 自信","医者 · 不安 · 失誉","此牌可指技巧、机敏、意志与自信；韦特也列出疾病、损失和受人设陷等另一组含义。","韦特既列“医者、术者”，也列精神困扰、不安与失誉，需结合语境辨读。"],["秘密 · 智慧 · 沉默","激情 · 自负 · 浅知","女祭司指尚未揭示的事、秘密与神秘，也关联沉默、坚持、智慧和知识。","逆位转向强烈的激情、自负，或只停留在表面的知识。"],["丰饶 · 行动 · 开端","真相显露 · 喜庆 · 犹疑","皇后可指丰饶、主动行动和长久的生命力；原著也并列疑惑、未知与困难。","逆位可指真相显露、复杂之事得到厘清与公开的喜庆；另一说则是犹疑不决。"],["稳定 · 权力 · 保护","仁慈 · 阻碍 · 不成熟","皇帝关联稳定、权力、保护、实现与权威，也强调理性和意志。","逆位既可能指仁慈、同情与信用，也可能指阻碍或不成熟。"],["婚盟 · 指引 · 约束","和睦 · 过度迁就","教皇可指婚姻与联盟，也可指束缚、服从；另有仁慈、灵感及可求助的指引者之意。","逆位指社交、相互理解与和睦；过度好心也可能变成软弱。"],["吸引 · 爱 · 克服考验","失败 · 计划落空","恋人关联吸引、爱情、美与克服考验。","逆位指失败或不明智的计划；另一说包括婚事受阻及各种不顺。"],["援助 · 胜利 · 冲突","争执 · 诉讼 · 失败","战车既指援助与胜利，也包含战争、傲慢、复仇及麻烦。","逆位多指骚乱、争吵、争端、诉讼或失败。"],["勇气 · 力量 · 成功","滥权 · 软弱 · 失和","力量指精力、行动、勇气与宽宏，也可指成功和荣誉。","逆位指专横或滥用力量，也可能是软弱、失和乃至失誉。"],["审慎 · 隐瞒 · 欺诈","遮掩 · 恐惧 · 过慎","隐者可指谨慎周密；韦特同时强调背叛、掩饰、欺诈与腐败等阴影含义。","逆位指隐藏、伪装、谋算、恐惧，或没有依据的过度谨慎。"],["命运 · 好运 · 成功","增加 · 丰裕 · 过剩","命运之轮关联命运、好运、成功、地位提升与幸福。","逆位在韦特原著中是增加、丰裕或过剩，并非必然厄运。"],["公平 · 正直 · 合法胜出","法律纠葛 · 偏见 · 苛刻","正义指公平、正直与诚实；在法律事项上，偏向应得的一方胜出。","逆位关联法律事务及纠葛，也可指偏执、成见或过度严苛。"],["智慧 · 牺牲 · 洞察","自私 · 群体牵制","倒吊人指智慧、谨慎、辨别、考验与牺牲，也涉及直觉和预感。","韦特将逆位与自私、群众或政治共同体相连；并未简单解释为“拖延”。"],["终结 · 损失 · 毁坏","停滞 · 麻木 · 希望破灭","死神在原著中首先指结束、死亡或毁坏，也可延伸为失去与计划受挫。","逆位指惰性、昏沉、僵化、无意识地行动，或希望破灭。"],["节制 · 管理 · 调和","失和 · 利益冲突 · 宗教事务","节制指节约、适度、审慎管理与调适安排。","逆位可指失和、不幸的结合与利益竞争；原著也列宗教、教会及神职相关事务。"],["暴烈 · 强迫 · 命定","不幸 · 软弱 · 盲目","恶魔关联破坏、暴力、猛烈的力量与命定之事；韦特特别说明“命定”不必然等于邪恶。","逆位指不利的命运、软弱、狭隘或盲目。"],["灾难 · 崩塌 · 欺骗","较轻的灾祸 · 压迫","高塔指困苦、逆境、欺骗、毁坏，尤其是难以预料的灾难。","逆位可指程度较轻的同类灾祸，也可指压迫、囚禁或暴政。"],["失去或希望 · 前景","傲慢 · 无力","星星在原著有并列而相反的说法：失去、被遗弃；另一说则是希望与光明前景。","逆位指傲慢、自高，或感到无力。"],["隐患 · 欺骗 · 恐惧","不稳定 · 较轻的误导","月亮指隐藏的敌意、危险、谣言、黑暗、恐惧、欺骗与错误。","逆位仍可有摇摆与误导，但欺骗和错误的程度可能较轻。"],["物质幸福 · 满足","幸福仍在 · 程度减弱","太阳指现实中的幸福、顺利的婚姻与满足。","逆位含义基本不变，只是幸福与顺遂的程度较轻。"],["更新 · 结果 · 转变","软弱 · 斟酌 · 裁决","审判指处境变化、更新与结果；原著另记一说，涉及诉讼中的重大损失。","逆位可指胆怯或软弱，也可指审议、决定与判决。"],["成功 · 回报 · 旅程","停滞 · 固守 · 不变","世界指确定的成功与回报，也可指旅行、迁居或地点改变。","逆位指惰性、固定、停滞或维持原状。"],["创造 · 开业 · 起源","衰落 · 破败 · 喜中带忧","权杖王牌指创造、发明、事业开端、出生与起源；另一说也关联财富或继承。","逆位指衰败、毁坏或失落，也可能是喜悦蒙上阴影。"],["富足或忧愁 · 远望","惊奇 · 情绪波动 · 恐惧","权杖二的两组原著解释难以合并：一边是财富与宏伟，一边是病痛、悲伤与屈辱。","逆位指意外、惊奇、迷醉或强烈情绪，也可能有麻烦和恐惧。"],["事业 · 贸易 · 合作","困境告终 · 辛劳暂停","权杖三指已建立的力量、事业、贸易、发现，也可指商业上的有力合作。","逆位指困难结束，逆境、辛劳或失望暂时停止。"],["安宁 · 和谐 · 繁荣","繁荣 · 喜悦 · 增长","权杖四指安居、休憩、和谐、繁荣与工作圆满。","韦特说逆位含义基本不变，仍是繁荣、增长、幸福与美好。"],["较量 · 竞争 · 争取","诉讼 · 争端 · 欺诈","权杖五像模拟战，也指争夺财富与机会的激烈竞争；有些解释还联想到获利。","逆位指诉讼、争执、诡计与矛盾。"],["胜利 · 喜讯 · 如愿","忧惧 · 背叛 · 延误","权杖六可指胜利者凯旋，也可指重大好消息与期待得到实现。","逆位指对威胁的忧惧、背叛或不忠，也可指无定期的拖延。"],["勇敢抗争 · 辩论 · 成功","困惑 · 焦虑 · 犹疑","权杖七指处于有利位置的勇敢抗争；在言语或商业上可表现为辩论、谈判与竞争。","逆位指困惑、窘迫与焦虑，并提醒避免犹疑不决。"],["迅速推进 · 消息 · 希望","嫉妒 · 争吵 · 内疚","权杖八指行动迅速、消息传递与事情快速推进，也可指爱情的箭。","逆位指嫉妒、内部争执、良心不安或家庭争吵。"],["抗争中的力量 · 延迟","障碍 · 逆境 · 灾祸","权杖九指遭遇攻击时仍能抵抗的力量，也可伴随延期或暂缓。","逆位指障碍、逆境或灾祸。"],["重压 · 成功的负担","困难 · 阴谋 · 反复","权杖十的首要含义是重压；即便获得财富或成功，也可能被其负担压住。原著另列伪装与背信。","逆位指困难、阻挠和暗中图谋。"],["使者 · 可靠 · 家庭消息","坏消息 · 不稳定","权杖侍从可指忠诚的年轻人、使者或信差，也可指与家庭有关的消息。","逆位指不好的消息、传闻、犹疑与不稳定。"],["离开 · 迁居 · 出行","决裂 · 中断 · 失和","权杖骑士主要指离开、出走、迁居或改变住所，也可代表友善的年轻人。","逆位指关系决裂、分离、事情中断或失和。"],["友善 · 忠诚 · 务实","节俭助人或嫉妒","权杖皇后可指友善、忠诚、令人信赖的女性，也关联对金钱的重视或商业上的成功。","逆位既可指节俭、热心助人，也可能在特定牌位和邻牌下表示反对、嫉妒或欺骗。"],["诚实 · 可靠 · 消息","严厉而宽容","权杖国王代表诚实、尽责而友善的人；韦特也提到意外继承的消息。","逆位仍可指好人，但态度严厉、朴素，同时保有宽容。"],["欢愉 · 满足 · 丰饶","虚情 · 不稳定 · 变动","圣杯王牌指真心、喜悦、满足、滋养、丰饶与幸福。","逆位指虚假的情意、变动与不稳定。"],["爱情 · 友谊 · 契合","原著未单列逆位","圣杯二指爱情、热情、友谊、结合、和谐与相互理解。","韦特原著没有为圣杯二单列逆位释义；这里不补造相反含义，仍以爱、友谊与契合为参考。"],["圆满 · 庆祝 · 疗愈","迅速完成 · 享乐过度","圣杯三指事情圆满、丰足、欢庆、胜利、慰藉与疗愈。","逆位指迅速办成或结束，也可指感官享乐过度。"],["厌倦 · 饱和 · 拒绝","新事物 · 新关系","圣杯四指厌倦、反感或因过度满足而失去兴趣，即使有新机会也难以从中得到安慰。","逆位指新事物、新征兆、新知识或新的人际关系。"],["失去 · 尚有余留","消息 · 联盟 · 回归","圣杯五指失去，但仍有部分留下；继承或所得可能不如预期，也可能带有苦涩。","逆位指消息、联盟、亲缘、祖辈、回归，也可能涉及不切实际的计划。"],["回忆 · 童年 · 往事","未来 · 更新 · 将来之事","圣杯六多指往事、童年回忆及过去的快乐；原著另有新关系和新环境的一说。","逆位转向未来、更新，以及即将发生的事。"],["想象 · 幻象 · 不持久","愿望 · 意志 · 计划","圣杯七指想象与幻想中的景象；即使有所获得，也欠缺持久和实质。","逆位指愿望、意志、决心与明确计划。"],["事物衰退 · 价值变轻","喜悦 · 幸福 · 宴乐","圣杯八通常指某件事渐渐衰退，或原以为重要的事其实分量有限；原著也记载相反的温和、荣誉之说。","逆位指强烈的喜悦、幸福与宴饮。"],["和谐 · 满足 · 成功","真诚或失误 · 含义不一","圣杯九指和谐、满足、身体舒适，也可指胜利和有利的结果。","逆位的记载并不统一：可指真诚、忠诚、自由，也可指错误与不完美。"],["真心满足 · 爱与友谊","虚情 · 愤怒 · 暴力","圣杯十指内心的满足、安宁，以及爱情与友谊的圆满。","逆位指虚假的安宁、愤怒或暴力。"],["消息 · 学习 · 反思","诱惑 · 欺骗 · 诡计","圣杯侍从可指愿意帮忙的年轻人，也指消息、学习、反思与思考。","逆位可指偏好、依恋与诱惑，也可指欺骗或诡计。"],["来访 · 提议 · 邀请","欺诈 · 两面性","圣杯骑士指到来、接近、传信、提议或邀请。","逆位指诡计、狡诈、诈骗、欺瞒和两面性。"],["诚挚 · 洞察 · 善意","记载分歧 · 可能失信","圣杯皇后指诚实、热心助人的女性，也关联洞察、智慧、幸福与美德。","逆位的原著说法分歧：有时仍指好人，有时指不可信任、品行失当或失誉。"],["公正 · 创造力 · 负责","不公 · 欺瞒 · 损失","圣杯国王可指负责而乐于帮助的人，也关联公正、艺术、科学与创造性的智慧。","逆位指不诚实、双重交易、不公、丑闻或重大损失。"],["征服 · 强力 · 极端","同样强力 · 结局不利","宝剑王牌指胜利、征服与极强的力量；在爱与恨两方面都可能走向极端。","逆位仍是强大的力量，但结果可能具有破坏性；另一说涉及孕育、增长。"],["武装下的平衡 · 和解","虚假 · 不忠 · 两面","宝剑二指平衡、勇气与和睦，也可指亲近；韦特提醒宝剑牌的有利含义应谨慎看待。","逆位指冒充、谎言、两面性或不忠。"],["分离 · 延迟 · 破裂","迷乱 · 错误 · 失序","宝剑三指远离、缺席、延迟、分离与关系破裂。","逆位指思想混乱、判断错误、损失与失序。"],["退隐 · 孤独 · 休憩","谨慎经营 · 防备","宝剑四指警觉、退隐、独处与如隐士般的安歇；原著还联想到流放与墓室。","逆位指审慎管理、节约与预防，也可能流于吝啬。"],["损失 · 受辱 · 毁坏","同样的损失 · 丧葬","宝剑五指降格、毁坏、耻辱、失去与受损。","逆位仍保留损失和破坏的含义；原著另列埋葬与丧礼。"],["旅程 · 渡水 · 使命","表白 · 公开 · 告白","宝剑六可指水路旅行、道路、使者、受托任务或权宜办法。","逆位指公开、声明、坦白；另一说是爱情的提议。"],["计划 · 尝试 · 不确定","忠告 · 流言","宝剑七可指谋划、尝试、希望与信心，也可指争吵或可能失败的计划；原著承认这些解释相互矛盾。","逆位可指有益的劝告与指引，也可指诽谤或闲言碎语。"],["坏消息 · 受困 · 危机","不安 · 阻碍 · 意外","宝剑八指坏消息、危机、受限的力量、冲突与诽谤，也可涉及疾病。","逆位指不安、困难、阻碍、意外或背叛。"],["绝望 · 失败 · 失落","怀疑 · 羞耻 · 合理恐惧","宝剑九在原著中指死亡、失败、延误、欺骗、失望与绝望等严重困境。","逆位指受困、怀疑、羞耻，以及有根据的恐惧。"],["痛苦 · 哀伤 · 荒凉","暂时获利 · 权势","宝剑十指痛苦、悲伤、眼泪与荒凉；韦特说明它并不专指暴力死亡。","逆位可指好处、收益、成功或权势，但这些并不持久。"],["警觉 · 监察 · 查探","更危险的监视 · 意外","宝剑侍从指权威、监察、警觉、查探与审视。","逆位突出这些行为较不利的一面，也可指突发情况、准备不足或疾病。"],["勇敢 · 技巧 · 冲突","鲁莽 · 无能 · 过度","宝剑骑士同时指勇气、技巧与防卫，也指愤怒、战争、破坏和对抗。","逆位指不谨慎、能力不足或过度挥霍。"],["丧失 · 分离 · 哀悼","恶意 · 偏执 · 欺骗","宝剑皇后关联守寡、悲伤、缺席、匮乏、哀悼与分离。","逆位指恶意、偏执、矫饰或欺骗。"],["判断 · 权威 · 法律","残酷 · 背信 · 恶意","宝剑国王指判断力及由此而来的权力、命令、法律与威严。","逆位指残酷、野蛮、背信或恶意。"],["满足 · 金钱 · 幸福","财富阴影 · 坏消息","星币王牌指圆满满足、幸福，也可指很快得到消息或金钱。","逆位仍可能有财富与舒适条件，但也指财富的弊端或坏消息。"],["嬉乐或纷扰 · 书信","勉强欢乐 · 文字事务","星币二一说指欢乐和休闲，另一说指书信消息、障碍与纷扰。","逆位指勉强表现的快乐、假装享受，也关联书写、文书与票据。"],["手艺 · 技能 · 声望","平庸 · 幼稚 · 软弱","星币三指行业、熟练劳动与技艺；原著也常将它视为声望与荣耀。","逆位指工作或其他方面的平庸、幼稚、琐碎与软弱。"],["守住财物 · 继承","悬而未决 · 延误","星币四指财物有保障、紧守已有之物，也可指礼物、遗产与继承。","逆位指悬而未决、延迟或遭到反对。"],["物质困境 · 匮乏","混乱 · 破败 · 不和","星币五主要指现实或财务上的困境；原著另记爱情、亲密关系的不同解法，并说两者难以调和。","逆位指混乱、毁坏、失和或挥霍。"],["馈赠 · 当前机会","贪求 · 嫉妒 · 幻想","星币六指赠予、礼物和满足；另一说提醒留意当前机会与已有的兴盛。","逆位指贪求、嫉妒、妄念或占有欲。"],["金钱 · 生意 · 交易","借贷引起的忧虑","星币七的原著解释彼此冲突；主要关乎金钱、生意与交易，也有争吵或纯真巧思之说。","逆位尤其指对拟借出的钱财感到忧虑。"],["工作 · 手艺 · 熟练","虚荣 · 贪婪 · 技巧滥用","星币八指工作、委托、手艺和商业技能，可能还在准备或练习阶段。","逆位指空洞的野心、虚荣、贪求，也可能是把聪明才智用在诡计上。"],["审慎 · 安全 · 成就","欺骗 · 背信 · 计划落空","星币九指谨慎、安全、成功、完成与辨别力。","逆位指欺诈、背信或计划落空。"],["财富 · 家族 · 传承","损失 · 风险 · 偶然赠与","星币十指收益、财富与家族事务，包括家世、档案和家庭居所。","逆位指偶然风险、损失、盗窃或赌博；有时也指赠与、嫁妆或养老金。"],["专心学习 · 管理 · 消息","挥霍 · 奢侈 · 坏消息","星币侍从指专注、学习、思考与管理；另一说指消息及其传递者。","逆位指挥霍、分心、奢侈或不利的消息。"],["实用 · 负责 · 正直","懒散 · 停滞 · 疏忽","星币骑士指有用、服务、责任感与现实事务中的正直。","逆位指懒散、停滞、灰心或疏忽，也可指消极的安逸。"],["富足 · 慷慨 · 安全","怀疑 · 恐惧 · 不信任","星币皇后指富足、慷慨、安稳与自由。","逆位指怀疑、悬念、恐惧或不信任。"],["商业能力 · 实现 · 成功","堕落 · 软弱 · 危险","星币国王指勇气、把想法落实的智慧，以及商业或数学等现实才能和成就。","逆位指恶习、软弱、腐败、危险或行为失当。"]];
export const plain=[["这张牌提醒你留意一时兴起和过度冒险，先看清自己要付出的代价。","问题可能出在疏忽或提不起劲；回到眼前最需要认真处理的小事。"],["你有办法和意志去处理这件事，但也要看清潜在的陷阱和损失。","别只看表面的能干；留意内在不安，必要时向专业人士求助。"],["有些信息还没浮现。先保留观察，安静地整理你已经知道的线索。","强烈的情绪或自以为懂了，可能让你忽略更深一层的事实。"],["这是让事情生长、付诸行动的时刻；同时承认你仍有疑问。","复杂之处也许正在变清楚，但别急着把犹豫装成确定。"],["稳定的安排、清晰的责任与决断，能给这件事一个可靠的支点。","柔和与体谅可能更有用；也检查是否有阻碍或不成熟的处理方式。"],["可以借助规则、承诺或有经验者的指引，也要看见其中的约束。","关系中的和气很可贵，但过度迁就可能让你失去自己的立场。"],["吸引和爱真实存在；眼前的考验需要双方认真面对。","期待中的结合或计划可能受阻，先面对不合适的部分。"],["行动能带来胜利或援助，但别让争胜心把事情推向冲突。","争执可能升级或让计划受挫，先处理分歧再谈推进。"],["勇气和行动力都在你手里；把力量用在真正重要的地方。","强硬可能变成滥权，退缩也可能让局面失衡，试着调整用力方式。"],["谨慎是必要的，同时要留心信息是否被隐藏或扭曲。","过度防备和遮掩会妨碍判断，试着分清真实风险与恐惧。"],["局势中有顺势而上的机会，做好准备迎接变化。","增长不一定是坏事，但太多也可能变成负担，留意分寸。"],["把事实、责任和公平放在前面，你的判断才更站得住脚。","偏见或过于严厉的尺度会让事情变复杂，尤其涉及规则时。"],["暂停和付出可能换来更清楚的判断；问问自己什么值得牺牲。","别只围着自己的得失打转，也看看群体或环境怎样影响选择。"],["某件事正在结束或失去原有形态，允许自己认真面对这份失落。","停在已经结束的事上，会让人麻木；先承认希望为何受挫。"],["节制、管理和调整，比急于求成更适合眼前的局面。","不同利益或观念可能难以合并，先找出真正的冲突点。"],["强烈的欲望或外力正在推动局面；先辨认它会造成什么伤害。","无力和盲目会放大不利处境，重新检查自己还有哪些选择。"],["突如其来的破坏可能打乱计划，先稳住现实中的安全与支持。","即使冲击较轻，压迫感仍值得正视，不必假装一切如常。"],["这张牌在原著中既可指失去，也可指希望；对照现实，看看哪一面更贴近你。","自负或无力感都可能遮住前景，试着回到可验证的事实。"],["信息不清时，危险和误解容易被放大；先核实，再做决定。","混乱可能有所减轻，但仍要留心摇摆的说法与不完整的事实。"],["你可以承认当下真实的满足与幸福，不必把好事说得太复杂。","好的一面还在，只是没那么充分；允许喜悦以较小的方式出现。"],["一个阶段正在转变并走向结果，回顾之后再决定下一步。","别让胆怯替你下结论；需要斟酌的事，慢慢作出判断。"],["已有的努力可能得到回报，也可能伴随旅行或生活地点的变化。","进展停住时，先看是什么让你固守原地。"],["创意或一项事业有了起点，把热情落实为真正能开始的行动。","衰退或失落会冲淡喜悦，先照顾受损的部分。"],["外在条件可能很丰厚，内心却仍有忧虑；两种感受可以同时存在。","意外让人惊喜也可能让人害怕，先给情绪一点缓冲。"],["事业已有基础，可以继续拓展、合作并寻找新的机会。","先前的艰难可能暂告一段落，允许自己停下来整理。"],["安稳、和睦与成果值得珍惜，也值得和重要的人分享。","原著的逆位仍是好意象：繁荣与愉快并未因为牌倒过来就消失。"],["意见相撞未必是坏事；弄清大家究竟在争什么。","争执若转为欺骗或诉讼，解决问题比赢下口角更重要。"],["努力可能得到认可或带来好消息，坦然接住这份进展。","担心失去成果会让人紧张；核实消息，也留意延误和失信。"],["你有守住立场的力量，辩论或竞争需要清楚的理由。","困惑会削弱行动，先确定哪一点最值得你坚持。"],["事情推进得很快，及时回应，同时看清方向。","速度放慢后可能浮现嫉妒、争吵或内疚，先处理关系中的刺。"],["即使遭遇阻力，你仍能撑住；延期不等于失败。","障碍可能比预想的多，先评估风险与资源。"],["成功也可能变成沉重负担；看看哪些责任压得你喘不过气。","麻烦与暗中阻挠需要逐项处理，别把所有事独自扛下。"],["留意来自他人或家庭的消息，可靠的沟通能帮你判断。","传闻或坏消息可能扰乱方向，先核实再回应。"],["离开、搬迁或改变环境可能是这张牌的核心，不只是“冲劲”。","分离或中断让计划改变，先接受已经出现的裂缝。"],["可以信任一份务实而友善的支持，也留意钱与关系如何交织。","有时只是节俭和乐于帮忙；若出现嫉妒，要看具体关系。"],["诚实和尽责比气势更有力量，也许会有意外的消息。","一个人可能严厉却并非恶意，试着分辨态度与用心。"],["真诚的情感与生活中的满足值得接纳和滋养。","情意或承诺若不够真，关系容易变得摇摆。"],["彼此的吸引、友谊或合作，建立在相互回应上。","原著没有给这张牌单独的逆位结论；先回到双方真实的感受与互动。"],["事情有了好结果，庆祝和疗愈都可以是这段经历的一部分。","顺利完成值得高兴，也留意享乐是否超过了自己的承受范围。"],["厌倦可能让你看不见面前的机会，先弄清自己为何提不起兴趣。","新的信息或关系正在进入视野，给它一点观察的空间。"],["失去的部分值得难过，但并非所有东西都已失去。","旧关系、消息或回归可能出现；别让不切实际的计划替代现实。"],["回忆能带来温度，也可能提醒你已离开的生活阶段。","视线从过去转向未来，新的关系和环境值得留意。"],["想象很多，但未必都能落地；挑出真正可实现的一项。","把愿望变成决定和计划，才能知道自己到底要什么。"],["你曾看重的事也许正在失去分量，允许自己重新评估。","原著逆位反而指向喜悦和欢聚，不必自动理解成阻碍。"],["你可以享受已经获得的满足和成果。","有些说法指真诚自由，有些说法指缺憾；要用现实情况辨别。"],["关系中的安宁与真心值得维护，也让彼此的快乐被看见。","表面的和睦若藏着怒气，先诚实面对冲突。"],["一则消息或一次学习值得认真思考，也可以接受他人的善意。","依恋和诱惑可能混在一起，留意承诺里有没有欺骗。"],["邀请或提议正在靠近，先听清它的具体内容。","漂亮的说辞不等于诚实，核实对方能否兑现。"],["温柔、洞察和可靠的支持正在发挥作用。","原著对逆位有不同说法；与其急着贴标签，不如看行动是否可信。"],["以公平和负责的态度处理问题，创造力也可以帮助你。","若出现不公或欺瞒，先保护重要的事实与利益。"],["你可能很想赢，但力量越大，越要想清楚胜利的代价。","强行推进可能得到糟糕的结果，先停下来重新衡量。"],["表面的平静来之不易，关系中的和解也需要谨慎。","别让谎言或两面做法破坏已经建立的信任。"],["分离或延误会让人受伤，允许自己承认这份痛。","思绪混乱时不宜急着定论，先把事实和情绪分开。"],["退开一步、独处和休息，可以让你从紧绷中恢复。","谨慎管理有帮助，但别让防备变成吝啬或过度控制。"],["这场争执或失去可能留下实际伤害，先承认损失。","逆位也没有轻松的“翻盘”；处理后续和告别同样重要。"],["旅程或过渡需要一个可行的办法，慢慢把事情带向下一站。","该说清的事或许到了公开的时候，坦白可能改变关系。"],["计划中既有希望也有不确定性，别把冒险当成已经成功。","忠告可能有用，流言也可能混进来，先分辨信息来源。"],["坏消息或限制可能让你难受，先找出真正受限的部分。","意外和阻碍仍在，留出余地应对变化。"],["失望或绝望感很沉重；此时不必独自承受。","怀疑和恐惧可能有现实依据，找可靠的人一起核实。"],["这是一张关于痛苦和终结的牌，不必把它夸大成必然的灾祸。","即使出现好转或收益，也未必长久，先稳住眼前。"],["观察和核对信息很重要，但别让警觉变成窥探。","缺乏准备时，突发消息更容易打乱你。"],["果断和勇气能推动事情，也可能把冲突推得更激烈。","急躁或能力准备不足时，先停一停再出手。"],["分离与失去可能是眼前的主题，允许自己承认难过。","严厉的话语可能带着偏见或恶意，先保护自己的边界。"],["用清晰的判断和规则处理问题，让权力承担相应责任。","权威若失去公正，会变成伤害；留意是否有人滥用位置。"],["现实中的收获或好消息值得珍惜，看看它能带来什么安稳。","有钱或资源不代表一定幸福，留意财富附带的代价。"],["你可能一边想轻松，一边被杂事搅动；先安排好优先次序。","勉强表现得开心会更累，把真实感受说清楚。"],["手艺和认真工作会被看见，能力也能带来声望。","敷衍或只做表面功夫，难以让成果站稳。"],["守住已有的资源有其必要，也想想自己为何抓得这么紧。","等待和阻力可能让计划停住，先处理具体卡点。"],["物质上的压力是真实的，先寻找可用的帮助与资源。","混乱和失和可能加重处境，越是困难越要避免挥霍。"],["给予与接受都可以带来满足，留意当下真正有用的支持。","如果付出背后夹着嫉妒或占有欲，就该重新谈清界限。"],["这张牌主要关乎钱与生意；原著的不同解释也提醒你别只看单一角度。","涉及借钱时，担忧值得认真对待，先确认偿还和风险。"],["持续工作和练习正在让本领更扎实。","技巧若只拿来钻空子，能力反而会伤害信任。"],["谨慎的积累正在带来安全感和成果。","计划或承诺可能不可靠，核实之后再投入。"],["家族、住处与长久积累的资源，值得一起放到时间里看。","损失或投机风险需要注意；也可能涉及赠与等偶然变化。"],["专心学习并把事务安排好，新的消息也值得留意。","分心或挥霍会消耗机会，坏消息先核实再处理。"],["踏实负责地完成眼前任务，就是这张牌的力量。","停滞和疏忽可能来自倦怠，先找回可持续的节奏。"],["丰足和安全感可以转化为慷慨，也要给自己留自由。","怀疑和不安若不断累积，先查清它们来自哪里。"],["务实的判断和专业能力，能把想法变成成果。","能力若失去操守就会带来风险，先守住原则。"]];
